//! This module defines journal receipts for container create requests that finish before JIT configuration delivery.

use crate::error::HostError;

const TABLE: &str = "CREATE TABLE IF NOT EXISTS capacity_reservation_pre_jit_create_responses (reservation_id INTEGER NOT NULL REFERENCES capacity_reservations(id), role TEXT NOT NULL CHECK (role IN ('runner', 'dind')), connection_id TEXT NOT NULL REFERENCES connection_scopes(connection_id), operation_id INTEGER NOT NULL REFERENCES connection_intents(id), engine_id TEXT NOT NULL CHECK (length(CAST(engine_id AS BLOB)) BETWEEN 1 AND 256), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), container_name TEXT NOT NULL CHECK (length(container_name) BETWEEN 1 AND 128), client_api_major INTEGER NOT NULL CHECK (client_api_major = 1), client_api_minor INTEGER NOT NULL CHECK (client_api_minor = 53), response_status INTEGER NOT NULL CHECK (response_status IN (400, 404, 409)), PRIMARY KEY (reservation_id, role), UNIQUE (reservation_id, container_name))";

const INSERT_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_create_response_insert_guard BEFORE INSERT ON capacity_reservation_pre_jit_create_responses WHEN NOT EXISTS (SELECT 1 FROM capacity_reservations AS reservation JOIN capacity_reservation_provisioning AS provisioning ON provisioning.reservation_id = reservation.id JOIN capacity_reservation_provisioning_state AS state ON state.reservation_id = reservation.id JOIN capacity_reservation_bootstrap_containers AS bootstrap ON bootstrap.reservation_id = reservation.id AND bootstrap.role = NEW.role JOIN connection_intents AS intent ON intent.id = provisioning.operation_id AND intent.connection_id = reservation.connection_id WHERE reservation.id = NEW.reservation_id AND reservation.connection_id = NEW.connection_id AND reservation.intent_id = NEW.operation_id AND reservation.state = 'reserved' AND reservation.engine_id = NEW.engine_id AND reservation.docker_root_digest = NEW.docker_root_digest AND intent.id = NEW.operation_id AND intent.kind = 'launch' AND intent.state = 'pending' AND intent.cleanup_proven = 0 AND provisioning.operation_id = NEW.operation_id AND provisioning.engine_id = NEW.engine_id AND provisioning.docker_root_digest = NEW.docker_root_digest AND state.resources_bound = 0 AND state.bootstrap_start_state = 'not_requested' AND state.jit_state = 'not_requested' AND state.publication_state = 'not_requested' AND state.delivery_state = 'not_requested' AND state.storage_cleanup_proven = 0 AND bootstrap.container_name = NEW.container_name AND bootstrap.create_state = 'requested' AND bootstrap.container_id IS NULL AND bootstrap.start_state = 'not_requested' AND EXISTS (SELECT 1 FROM capacity_reservation_pre_jit_create_specs AS spec WHERE spec.reservation_id = NEW.reservation_id AND spec.role = NEW.role AND spec.connection_id = NEW.connection_id AND spec.operation_id = NEW.operation_id AND spec.engine_id = NEW.engine_id AND spec.docker_root_digest = NEW.docker_root_digest AND spec.container_name = NEW.container_name)) BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT create response'); END";

const NO_UPDATE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_create_response_no_update BEFORE UPDATE ON capacity_reservation_pre_jit_create_responses BEGIN SELECT RAISE(ABORT, 'immutable pre-JIT create response'); END";
const NO_DELETE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_create_response_no_delete BEFORE DELETE ON capacity_reservation_pre_jit_create_responses BEGIN SELECT RAISE(ABORT, 'retained pre-JIT create response'); END";
const CREATE_SPECS: &str = "CREATE TABLE IF NOT EXISTS capacity_reservation_pre_jit_create_specs (reservation_id INTEGER NOT NULL REFERENCES capacity_reservations(id), role TEXT NOT NULL CHECK (role IN ('runner', 'dind')), connection_id TEXT NOT NULL REFERENCES connection_scopes(connection_id), operation_id INTEGER NOT NULL REFERENCES connection_intents(id), engine_id TEXT NOT NULL CHECK (length(CAST(engine_id AS BLOB)) BETWEEN 1 AND 256), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), container_name TEXT NOT NULL CHECK (length(container_name) BETWEEN 1 AND 128), image_runtime_id TEXT NOT NULL CHECK (length(image_runtime_id) = 71 AND image_runtime_id GLOB 'sha256:*' AND substr(image_runtime_id, 8) NOT GLOB '*[^0-9a-f]*'), image_source_sha TEXT NOT NULL CHECK (length(image_source_sha) = 40 AND image_source_sha NOT GLOB '*[^0-9a-f]*'), runner_cpu_millicores INTEGER NOT NULL CHECK (runner_cpu_millicores > 0), runner_memory_bytes INTEGER NOT NULL CHECK (runner_memory_bytes > 0), dind_cpu_millicores INTEGER NOT NULL CHECK (dind_cpu_millicores > 0), dind_memory_bytes INTEGER NOT NULL CHECK (dind_memory_bytes > 0), admission_memory_bytes INTEGER NOT NULL CHECK (admission_memory_bytes > 0), spec_sha256 TEXT NOT NULL CHECK (length(spec_sha256) = 64 AND spec_sha256 NOT GLOB '*[^0-9a-f]*'), PRIMARY KEY (reservation_id, role), UNIQUE (reservation_id, container_name))";
const CREATE_SPEC_INSERT_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_create_spec_insert_guard BEFORE INSERT ON capacity_reservation_pre_jit_create_specs WHEN NOT EXISTS (SELECT 1 FROM capacity_reservations AS reservation JOIN capacity_reservation_provisioning AS provisioning ON provisioning.reservation_id = reservation.id JOIN capacity_reservation_provisioning_state AS state ON state.reservation_id = reservation.id JOIN connection_intents AS intent ON intent.id = provisioning.operation_id AND intent.connection_id = reservation.connection_id JOIN capacity_reservation_bootstrap_containers AS bootstrap ON bootstrap.reservation_id = reservation.id AND bootstrap.role = NEW.role WHERE reservation.id = NEW.reservation_id AND reservation.connection_id = NEW.connection_id AND reservation.intent_id = NEW.operation_id AND reservation.state = 'reserved' AND reservation.engine_id = NEW.engine_id AND reservation.docker_root_digest = NEW.docker_root_digest AND reservation.cpu_millicores = NEW.runner_cpu_millicores + NEW.dind_cpu_millicores AND reservation.memory_bytes = NEW.runner_memory_bytes + NEW.dind_memory_bytes AND intent.id = NEW.operation_id AND intent.kind = 'launch' AND intent.state = 'pending' AND intent.cleanup_proven = 0 AND provisioning.operation_id = NEW.operation_id AND provisioning.engine_id = NEW.engine_id AND provisioning.docker_root_digest = NEW.docker_root_digest AND state.resources_bound = 0 AND state.bootstrap_start_state = 'not_requested' AND state.jit_state = 'not_requested' AND state.publication_state = 'not_requested' AND state.delivery_state = 'not_requested' AND state.storage_cleanup_proven = 0 AND bootstrap.container_name = NEW.container_name AND bootstrap.create_state = 'requested' AND bootstrap.container_id IS NULL AND bootstrap.start_state = 'not_requested') BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT create spec'); END";
const CREATE_SPEC_NO_UPDATE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_create_spec_no_update BEFORE UPDATE ON capacity_reservation_pre_jit_create_specs BEGIN SELECT RAISE(ABORT, 'immutable pre-JIT create spec'); END";
const CREATE_SPEC_NO_DELETE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_create_spec_no_delete BEFORE DELETE ON capacity_reservation_pre_jit_create_specs BEGIN SELECT RAISE(ABORT, 'retained pre-JIT create spec'); END";

const CLAIMS: &str = "CREATE TABLE IF NOT EXISTS capacity_reservation_pre_jit_cleanup_claims (reservation_id INTEGER PRIMARY KEY REFERENCES capacity_reservations(id), connection_id TEXT NOT NULL REFERENCES connection_scopes(connection_id), operation_id INTEGER NOT NULL REFERENCES connection_intents(id), engine_id TEXT NOT NULL CHECK (length(CAST(engine_id AS BLOB)) BETWEEN 1 AND 256), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), snapshot_sha256 TEXT NOT NULL CHECK (length(snapshot_sha256) = 64 AND snapshot_sha256 NOT GLOB '*[^0-9a-f]*'), claim_generation INTEGER NOT NULL CHECK (claim_generation > 0), lease_until INTEGER NOT NULL CHECK (lease_until > 0), phase TEXT NOT NULL CHECK (phase = 'claimed'))";
const CLAIM_INSERT_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_claim_insert_guard BEFORE INSERT ON capacity_reservation_pre_jit_cleanup_claims WHEN NOT EXISTS (SELECT 1 FROM capacity_reservations AS reservation JOIN capacity_reservation_provisioning AS provisioning ON provisioning.reservation_id = reservation.id JOIN capacity_reservation_provisioning_state AS state ON state.reservation_id = reservation.id JOIN connection_intents AS intent ON intent.id = provisioning.operation_id AND intent.connection_id = reservation.connection_id WHERE reservation.id = NEW.reservation_id AND reservation.connection_id = NEW.connection_id AND reservation.intent_id = NEW.operation_id AND reservation.state = 'uncertain' AND reservation.engine_id = NEW.engine_id AND reservation.docker_root_digest = NEW.docker_root_digest AND intent.id = NEW.operation_id AND intent.kind = 'launch' AND intent.state = 'uncertain' AND intent.cleanup_proven = 0 AND provisioning.operation_id = NEW.operation_id AND provisioning.engine_id = NEW.engine_id AND provisioning.docker_root_digest = NEW.docker_root_digest AND state.resources_bound = 0 AND state.bootstrap_start_state = 'not_requested' AND state.jit_state = 'not_requested' AND state.publication_state = 'not_requested' AND state.delivery_state = 'not_requested' AND state.storage_cleanup_proven = 0 AND EXISTS (SELECT 1 FROM capacity_reservation_pre_jit_create_responses AS response WHERE response.reservation_id = NEW.reservation_id AND response.connection_id = NEW.connection_id AND response.operation_id = NEW.operation_id AND response.engine_id = NEW.engine_id AND response.docker_root_digest = NEW.docker_root_digest)) BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT cleanup claim'); END";
const CLAIM_UPDATE_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_claim_update_guard BEFORE UPDATE ON capacity_reservation_pre_jit_cleanup_claims WHEN OLD.reservation_id != NEW.reservation_id OR OLD.connection_id != NEW.connection_id OR OLD.operation_id != NEW.operation_id OR OLD.engine_id != NEW.engine_id OR OLD.docker_root_digest != NEW.docker_root_digest OR OLD.snapshot_sha256 != NEW.snapshot_sha256 OR NEW.claim_generation != OLD.claim_generation + 1 OR NEW.lease_until <= OLD.lease_until OR OLD.lease_until > CAST(strftime('%s', 'now') AS INTEGER) OR OLD.phase != 'claimed' OR NEW.phase != 'claimed' BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT cleanup claim update'); END";
const CLAIM_NO_DELETE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_claim_no_delete BEFORE DELETE ON capacity_reservation_pre_jit_cleanup_claims BEGIN SELECT RAISE(ABORT, 'retained pre-JIT cleanup claim'); END";

const PROGRESS: &str = "CREATE TABLE IF NOT EXISTS capacity_reservation_pre_jit_cleanup_progress (reservation_id INTEGER PRIMARY KEY REFERENCES capacity_reservations(id), connection_id TEXT NOT NULL REFERENCES connection_scopes(connection_id), operation_id INTEGER NOT NULL REFERENCES connection_intents(id), engine_id TEXT NOT NULL CHECK (length(CAST(engine_id AS BLOB)) BETWEEN 1 AND 256), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), snapshot_sha256 TEXT NOT NULL CHECK (length(snapshot_sha256) = 64 AND snapshot_sha256 NOT GLOB '*[^0-9a-f]*'), claim_generation INTEGER NOT NULL CHECK (claim_generation > 0), phase TEXT NOT NULL CHECK (phase IN ('claimed', 'bootstrap_absent', 'initializer_absent', 'storage_absent', 'network_absent', 'settled')), evidence_sha256 TEXT NOT NULL CHECK (length(evidence_sha256) = 64 AND evidence_sha256 NOT GLOB '*[^0-9a-f]*'))";
const PROGRESS_INSERT_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_progress_insert_guard BEFORE INSERT ON capacity_reservation_pre_jit_cleanup_progress WHEN NEW.phase != 'claimed' OR NEW.evidence_sha256 != NEW.snapshot_sha256 OR NOT EXISTS (SELECT 1 FROM capacity_reservation_pre_jit_cleanup_claims AS claim WHERE claim.reservation_id = NEW.reservation_id AND claim.connection_id = NEW.connection_id AND claim.operation_id = NEW.operation_id AND claim.engine_id = NEW.engine_id AND claim.docker_root_digest = NEW.docker_root_digest AND claim.snapshot_sha256 = NEW.snapshot_sha256 AND claim.claim_generation = NEW.claim_generation AND claim.lease_until > CAST(strftime('%s', 'now') AS INTEGER) AND claim.phase = 'claimed') BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT cleanup progress'); END";
const PROGRESS_UPDATE_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_progress_update_guard BEFORE UPDATE ON capacity_reservation_pre_jit_cleanup_progress WHEN OLD.reservation_id != NEW.reservation_id OR OLD.connection_id != NEW.connection_id OR OLD.operation_id != NEW.operation_id OR OLD.engine_id != NEW.engine_id OR OLD.docker_root_digest != NEW.docker_root_digest OR OLD.snapshot_sha256 != NEW.snapshot_sha256 OR length(NEW.evidence_sha256) != 64 OR NEW.evidence_sha256 GLOB '*[^0-9a-f]*' OR NOT EXISTS (SELECT 1 FROM capacity_reservation_pre_jit_cleanup_claims AS claim WHERE claim.reservation_id = NEW.reservation_id AND claim.connection_id = NEW.connection_id AND claim.operation_id = NEW.operation_id AND claim.engine_id = NEW.engine_id AND claim.docker_root_digest = NEW.docker_root_digest AND claim.snapshot_sha256 = NEW.snapshot_sha256 AND claim.claim_generation = NEW.claim_generation AND claim.lease_until > CAST(strftime('%s', 'now') AS INTEGER) AND claim.phase = 'claimed') OR NOT ((NEW.claim_generation = OLD.claim_generation + 1 AND NEW.phase = OLD.phase AND NEW.evidence_sha256 = OLD.evidence_sha256) OR (NEW.claim_generation = OLD.claim_generation AND ((OLD.phase = 'claimed' AND NEW.phase = 'bootstrap_absent') OR (OLD.phase = 'bootstrap_absent' AND NEW.phase = 'initializer_absent') OR (OLD.phase = 'initializer_absent' AND NEW.phase = 'storage_absent') OR (OLD.phase = 'storage_absent' AND NEW.phase = 'network_absent') OR (OLD.phase = 'network_absent' AND NEW.phase = 'settled')))) BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT cleanup progress update'); END";
const PROGRESS_NO_DELETE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_progress_no_delete BEFORE DELETE ON capacity_reservation_pre_jit_cleanup_progress BEGIN SELECT RAISE(ABORT, 'retained pre-JIT cleanup progress'); END";

const PROBES: &str = "CREATE TABLE IF NOT EXISTS capacity_reservation_pre_jit_cleanup_probes (probe_operation_id TEXT PRIMARY KEY REFERENCES resource_probe_operations(operation_id), reservation_id INTEGER NOT NULL REFERENCES capacity_reservations(id), claim_generation INTEGER NOT NULL CHECK (claim_generation > 0), connection_id TEXT NOT NULL REFERENCES connection_scopes(connection_id), operation_id INTEGER NOT NULL REFERENCES connection_intents(id), engine_id TEXT NOT NULL CHECK (length(CAST(engine_id AS BLOB)) BETWEEN 1 AND 256), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), snapshot_sha256 TEXT NOT NULL CHECK (length(snapshot_sha256) = 64 AND snapshot_sha256 NOT GLOB '*[^0-9a-f]*'), profile_generation_id TEXT NOT NULL REFERENCES host_storage_profiles(generation_id), profile_digest TEXT NOT NULL CHECK (length(profile_digest) = 64 AND profile_digest NOT GLOB '*[^0-9a-f]*'), UNIQUE (reservation_id, claim_generation))";
const PROBE_INSERT_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_probe_insert_guard BEFORE INSERT ON capacity_reservation_pre_jit_cleanup_probes WHEN NOT EXISTS (SELECT 1 FROM capacity_reservation_pre_jit_cleanup_claims AS claim JOIN capacity_reservation_pre_jit_cleanup_progress AS progress ON progress.reservation_id = claim.reservation_id AND progress.connection_id = claim.connection_id AND progress.operation_id = claim.operation_id AND progress.engine_id = claim.engine_id AND progress.docker_root_digest = claim.docker_root_digest AND progress.snapshot_sha256 = claim.snapshot_sha256 AND progress.claim_generation = claim.claim_generation JOIN capacity_reservations AS reservation ON reservation.id = claim.reservation_id JOIN capacity_reservation_provisioning AS provisioning ON provisioning.reservation_id = reservation.id JOIN host_storage_profile_current AS current_profile ON current_profile.singleton = 1 AND current_profile.generation_id = NEW.profile_generation_id JOIN host_storage_profiles AS profile ON profile.generation_id = current_profile.generation_id JOIN resource_probe_operations AS probe ON probe.operation_id = NEW.probe_operation_id JOIN host_operation_leases AS lease ON lease.singleton = 1 AND lease.operation_id = probe.operation_id WHERE claim.reservation_id = NEW.reservation_id AND claim.connection_id = NEW.connection_id AND claim.operation_id = NEW.operation_id AND claim.engine_id = NEW.engine_id AND claim.docker_root_digest = NEW.docker_root_digest AND claim.snapshot_sha256 = NEW.snapshot_sha256 AND claim.claim_generation = NEW.claim_generation AND claim.lease_until > CAST(strftime('%s', 'now') AS INTEGER) AND claim.phase = 'claimed' AND progress.phase = 'network_absent' AND reservation.connection_id = NEW.connection_id AND reservation.intent_id = NEW.operation_id AND reservation.state = 'uncertain' AND provisioning.operation_id = NEW.operation_id AND provisioning.engine_id = NEW.engine_id AND provisioning.docker_root_digest = NEW.docker_root_digest AND provisioning.profile_generation_id = NEW.profile_generation_id AND provisioning.profile_digest = NEW.profile_digest AND profile.profile_digest = NEW.profile_digest AND probe.helper_role = 'resource-probe' AND probe.role = 'resource-probe' AND probe.probe_purpose = 'capacity' AND probe.phase = 'prepared' AND probe.engine_id = NEW.engine_id AND probe.docker_root_digest = NEW.docker_root_digest AND lease.state = 'reserved' AND lease.engine_id = NEW.engine_id AND lease.docker_root_digest = NEW.docker_root_digest AND lease.operation_name = probe.operation_name AND lease.container_id IS NULL) BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT cleanup probe'); END";
const PROBE_NO_UPDATE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_probe_no_update BEFORE UPDATE ON capacity_reservation_pre_jit_cleanup_probes BEGIN SELECT RAISE(ABORT, 'immutable pre-JIT cleanup probe'); END";
const PROBE_NO_DELETE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_probe_no_delete BEFORE DELETE ON capacity_reservation_pre_jit_cleanup_probes BEGIN SELECT RAISE(ABORT, 'retained pre-JIT cleanup probe'); END";

const SETTLEMENT: &str = "CREATE TABLE IF NOT EXISTS capacity_reservation_pre_jit_cleanup_settlements (reservation_id INTEGER NOT NULL REFERENCES capacity_reservations(id), claim_generation INTEGER NOT NULL CHECK (claim_generation > 0), connection_id TEXT NOT NULL REFERENCES connection_scopes(connection_id), operation_id INTEGER NOT NULL REFERENCES connection_intents(id), engine_id TEXT NOT NULL CHECK (length(CAST(engine_id AS BLOB)) BETWEEN 1 AND 256), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), snapshot_sha256 TEXT NOT NULL CHECK (length(snapshot_sha256) = 64 AND snapshot_sha256 NOT GLOB '*[^0-9a-f]*'), probe_operation_id TEXT NOT NULL UNIQUE REFERENCES resource_probe_operations(operation_id), probe_operation_name TEXT NOT NULL CHECK (length(probe_operation_name) BETWEEN 1 AND 128), probe_container_id TEXT NOT NULL CHECK (length(probe_container_id) BETWEEN 12 AND 256), profile_generation_id TEXT NOT NULL REFERENCES host_storage_profiles(generation_id), profile_digest TEXT NOT NULL CHECK (length(profile_digest) = 64 AND profile_digest NOT GLOB '*[^0-9a-f]*'), observed_at_unix_ms INTEGER NOT NULL CHECK (observed_at_unix_ms > 0), sample_evidence_sha256 TEXT NOT NULL CHECK (length(sample_evidence_sha256) = 64 AND sample_evidence_sha256 NOT GLOB '*[^0-9a-f]*'), outcome TEXT NOT NULL CHECK (outcome IN ('held_at_capacity', 'capacity_available')), PRIMARY KEY (reservation_id, claim_generation))";
const SETTLEMENT_POOL: &str = "CREATE TABLE IF NOT EXISTS capacity_reservation_pre_jit_cleanup_settlement_pools (reservation_id INTEGER NOT NULL, claim_generation INTEGER NOT NULL, pool_id TEXT NOT NULL CHECK (length(pool_id) = 64 AND pool_id NOT GLOB '*[^0-9a-f]*'), filesystem_instance_digest TEXT NOT NULL CHECK (length(filesystem_instance_digest) = 64 AND filesystem_instance_digest NOT GLOB '*[^0-9a-f]*'), medium TEXT NOT NULL CHECK (medium = 'disk'), filesystem_kind TEXT NOT NULL CHECK (filesystem_kind IN ('btrfs', 'other')), total_bytes INTEGER NOT NULL CHECK (total_bytes > 0), available_bytes INTEGER NOT NULL CHECK (available_bytes BETWEEN 0 AND total_bytes), total_inodes INTEGER NOT NULL CHECK (total_inodes >= 0), available_inodes INTEGER NOT NULL CHECK (available_inodes BETWEEN 0 AND total_inodes), PRIMARY KEY (reservation_id, claim_generation, pool_id), FOREIGN KEY (reservation_id, claim_generation) REFERENCES capacity_reservation_pre_jit_cleanup_settlements(reservation_id, claim_generation))";
const SETTLEMENT_INSERT_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_settlement_insert_guard BEFORE INSERT ON capacity_reservation_pre_jit_cleanup_settlements WHEN NOT EXISTS (SELECT 1 FROM capacity_reservation_pre_jit_cleanup_claims AS claim JOIN capacity_reservation_pre_jit_cleanup_progress AS progress ON progress.reservation_id = claim.reservation_id AND progress.connection_id = claim.connection_id AND progress.operation_id = claim.operation_id AND progress.engine_id = claim.engine_id AND progress.docker_root_digest = claim.docker_root_digest AND progress.snapshot_sha256 = claim.snapshot_sha256 AND progress.claim_generation = claim.claim_generation JOIN capacity_reservations AS reservation ON reservation.id = claim.reservation_id JOIN capacity_reservation_provisioning AS provisioning ON provisioning.reservation_id = reservation.id JOIN host_storage_profile_current AS current_profile ON current_profile.singleton = 1 AND current_profile.generation_id = NEW.profile_generation_id JOIN host_storage_profiles AS current_profile_row ON current_profile_row.generation_id = current_profile.generation_id JOIN resource_probe_operations AS probe ON probe.operation_id = NEW.probe_operation_id JOIN host_operation_leases AS lease ON lease.singleton = 1 AND lease.operation_id = probe.operation_id JOIN capacity_reservation_pre_jit_cleanup_probes AS prepared ON prepared.probe_operation_id = probe.operation_id WHERE prepared.reservation_id = NEW.reservation_id AND prepared.claim_generation = NEW.claim_generation AND prepared.connection_id = NEW.connection_id AND prepared.operation_id = NEW.operation_id AND prepared.engine_id = NEW.engine_id AND prepared.docker_root_digest = NEW.docker_root_digest AND prepared.snapshot_sha256 = NEW.snapshot_sha256 AND prepared.profile_generation_id = NEW.profile_generation_id AND prepared.profile_digest = NEW.profile_digest AND claim.reservation_id = NEW.reservation_id AND claim.connection_id = NEW.connection_id AND claim.operation_id = NEW.operation_id AND claim.engine_id = NEW.engine_id AND claim.docker_root_digest = NEW.docker_root_digest AND claim.snapshot_sha256 = NEW.snapshot_sha256 AND claim.claim_generation = NEW.claim_generation AND claim.lease_until > CAST(strftime('%s', 'now') AS INTEGER) AND claim.phase = 'claimed' AND progress.phase = 'network_absent' AND reservation.connection_id = NEW.connection_id AND reservation.intent_id = NEW.operation_id AND reservation.state = 'uncertain' AND provisioning.operation_id = NEW.operation_id AND provisioning.engine_id = NEW.engine_id AND provisioning.docker_root_digest = NEW.docker_root_digest AND provisioning.profile_generation_id = NEW.profile_generation_id AND provisioning.profile_digest = NEW.profile_digest AND current_profile.generation_id = provisioning.profile_generation_id AND current_profile_row.profile_digest = provisioning.profile_digest AND probe.helper_role = 'resource-probe' AND probe.role = 'resource-probe' AND probe.probe_purpose = 'capacity' AND probe.phase = 'removed' AND probe.engine_id = NEW.engine_id AND probe.docker_root_digest = NEW.docker_root_digest AND probe.operation_name = NEW.probe_operation_name AND probe.container_id = NEW.probe_container_id AND lease.state = 'released' AND lease.engine_id = NEW.engine_id AND lease.docker_root_digest = NEW.docker_root_digest AND lease.operation_name = NEW.probe_operation_name AND lease.container_id = NEW.probe_container_id) BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT cleanup settlement'); END";
const SETTLEMENT_POOL_INSERT_GUARD: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_settlement_pool_insert_guard BEFORE INSERT ON capacity_reservation_pre_jit_cleanup_settlement_pools WHEN NOT EXISTS (SELECT 1 FROM capacity_reservation_pre_jit_cleanup_settlements AS sample JOIN host_storage_profile_pools AS policy ON policy.generation_id = sample.profile_generation_id AND policy.pool_id = NEW.pool_id JOIN capacity_reservation_provisioning_pools AS reserved ON reserved.reservation_id = sample.reservation_id AND reserved.scope = 'shared-disk' AND reserved.medium = 'disk' AND reserved.pool_id = NEW.pool_id WHERE sample.reservation_id = NEW.reservation_id AND sample.claim_generation = NEW.claim_generation AND policy.medium = 'disk' AND reserved.filesystem_instance_digest = NEW.filesystem_instance_digest) BEGIN SELECT RAISE(ABORT, 'invalid pre-JIT sampled pool'); END";
const SETTLEMENT_NO_UPDATE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_settlement_no_update BEFORE UPDATE ON capacity_reservation_pre_jit_cleanup_settlements BEGIN SELECT RAISE(ABORT, 'immutable pre-JIT cleanup settlement'); END";
const SETTLEMENT_NO_DELETE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_settlement_no_delete BEFORE DELETE ON capacity_reservation_pre_jit_cleanup_settlements BEGIN SELECT RAISE(ABORT, 'retained pre-JIT cleanup settlement'); END";
const SETTLEMENT_POOL_NO_UPDATE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_settlement_pool_no_update BEFORE UPDATE ON capacity_reservation_pre_jit_cleanup_settlement_pools BEGIN SELECT RAISE(ABORT, 'immutable pre-JIT sample'); END";
const SETTLEMENT_POOL_NO_DELETE: &str = "CREATE TRIGGER IF NOT EXISTS pre_jit_cleanup_settlement_pool_no_delete BEFORE DELETE ON capacity_reservation_pre_jit_cleanup_settlement_pools BEGIN SELECT RAISE(ABORT, 'retained pre-JIT sample'); END";

