mod tests;

pub(super) async fn bootstrap(connection: &turso::Connection) -> Result<(), HostError> {
    for statement in [
        TABLE,
        CREATE_SPECS,
        CREATE_SPEC_INSERT_GUARD,
        CREATE_SPEC_NO_UPDATE,
        CREATE_SPEC_NO_DELETE,
        INSERT_GUARD,
        NO_UPDATE,
        NO_DELETE,
        CLAIMS,
        CLAIM_INSERT_GUARD,
        CLAIM_UPDATE_GUARD,
        CLAIM_NO_DELETE,
        PROGRESS,
        PROGRESS_INSERT_GUARD,
        PROGRESS_UPDATE_GUARD,
        PROGRESS_NO_DELETE,
        PROBES,
        PROBE_INSERT_GUARD,
        PROBE_NO_UPDATE,
        PROBE_NO_DELETE,
        SETTLEMENT,
        SETTLEMENT_POOL,
        SETTLEMENT_INSERT_GUARD,
        SETTLEMENT_POOL_INSERT_GUARD,
        SETTLEMENT_NO_UPDATE,
        SETTLEMENT_NO_DELETE,
        SETTLEMENT_POOL_NO_UPDATE,
        SETTLEMENT_POOL_NO_DELETE,
    ] {
        connection
            .execute(statement, ())
            .await
            .map_err(|_| HostError::Journal)?;
    }
    Ok(())
}

